import 'dart:io'; void main() { var f = File('lib/main.dart'); var c = f.readAsStringSync(); c = c.replaceAll('FontWeight.bold', 'FontWeight.w500'); c = c.replaceAll('FontWeight.w700', 'FontWeight.w500'); c = c.replaceAll('FontWeight.w800', 'FontWeight.w500'); c = c.replaceAll('FontWeight.w900', 'FontWeight.w500'); c = c.replaceAll('FontWeight.w600', 'FontWeight.w500'); f.writeAsStringSync(c); }
